-- SOURCE: purchase_payment_terms_partial.sql
-- Preparation only. No execution grants or historical payment backfill.
-- Credit creates a balance, not a cash movement. Future payments need their
-- own audited/idempotent operation before they can change these amounts.

set local lock_timeout = '3s';
set local statement_timeout = '30s';

alter table public.purchases
    add column if not exists payment_condition text,
    add column if not exists payment_method text,
    add column if not exists credit_days integer,
    add column if not exists due_date date,
    add column if not exists paid_amount double precision,
    add column if not exists balance_due double precision;
alter table public.purchases alter column cash_source drop not null;

do $$
begin
    if not exists (select 1 from pg_constraint
        where conrelid = 'public.purchases'::regclass
          and conname = 'purchases_payment_terms_valid') then
        alter table public.purchases add constraint purchases_payment_terms_valid check ((
            (payment_condition is null and payment_method is null and credit_days is null
                and due_date is null and paid_amount is null and balance_due is null)
            or
            (payment_condition in ('contado', 'credito')
                and total >= 0 and total < 'Infinity'::double precision
                and paid_amount >= 0 and paid_amount < 'Infinity'::double precision
                and balance_due >= 0 and balance_due < 'Infinity'::double precision
                and paid_amount <= total and balance_due <= total
                and abs(paid_amount + balance_due - total) <= greatest(0.000001, abs(total) * 1e-10)
                and (
                    (payment_condition = 'contado' and credit_days is null and due_date is null
                        and balance_due = 0 and paid_amount = total
                        and ((payment_method = 'efectivo' and cash_source in ('caja', 'cajero'))
                            or (payment_method in ('tarjeta', 'transferencia') and cash_source = payment_method)))
                    or (payment_condition = 'credito' and provider_id is not null
                        and credit_days >= 0 and due_date is not null
                        and payment_method is null and cash_source is null)
                ))
        ) is true);
    end if;
end;
$$;

-- SOURCE: owner_transaction_sync_partial.sql
-- Preparation only: do not deploy until the client, policies and real schema
-- have been validated together. Existing clients are not idempotent.
-- Requires purchase_payment_terms_partial.sql for purchase snapshots.


alter table public.sales_history
  add column if not exists sync_client_id uuid;
alter table public.purchases
  add column if not exists sync_client_id uuid;

create unique index if not exists sales_history_sync_client_id_key
  on public.sales_history (sync_client_id);
create unique index if not exists purchases_sync_client_id_key
  on public.purchases (sync_client_id);

create table if not exists public.owner_transaction_sync_requests (
  request_id uuid primary key,
  actor_id uuid not null,
  billar_id text not null,
  kind text not null,
  request_payload jsonb not null,
  result_id bigint,
  completed boolean not null default false
);
alter table public.owner_transaction_sync_requests enable row level security;
revoke all on public.owner_transaction_sync_requests from public, anon, authenticated;

create or replace function public.sync_owner_sale(
  p_request_id uuid,
  p_billar_id text,
  p_cloud_id bigint,
  p_sale jsonb,
  p_details jsonb
)
returns bigint
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
declare
  actor uuid := auth.uid();
  v_result_id bigint;
  payload jsonb;
  request_row public.owner_transaction_sync_requests%rowtype;
begin
  if actor is null or p_request_id is null or p_billar_id is null
      or btrim(p_billar_id) = '' or jsonb_typeof(p_sale) is distinct from 'object'
      or jsonb_typeof(p_details) is distinct from 'array' then
    raise exception 'Datos de sincronización inválidos.' using errcode = '22023';
  end if;
  perform 1 from public.billar_settings s
  join public.business_memberships m
    on m.user_id = s.user_id and m.billar_id = s.billar_id
  where s.user_id = actor and s.billar_id = p_billar_id
    and m.role = 'admin' and m.is_active and not m.must_change_password
  for share of s, m;
  if not found then
    raise exception 'Se requiere un administrador activo del billar.' using errcode = '42501';
  end if;

  payload := jsonb_build_object('cloud_id', p_cloud_id, 'sale', p_sale, 'details', p_details);
  insert into public.owner_transaction_sync_requests (
    request_id, actor_id, billar_id, kind, request_payload
  ) values (p_request_id, actor, p_billar_id, 'sale', payload)
  on conflict (request_id) do nothing;
  select * into strict request_row
  from public.owner_transaction_sync_requests
  where request_id = p_request_id for update;
  if request_row.actor_id <> actor or request_row.billar_id <> p_billar_id
      or request_row.kind <> 'sale' or request_row.request_payload <> payload then
    raise exception 'El identificador de sincronización ya fue utilizado.' using errcode = '23505';
  end if;
  if request_row.completed then
    if not exists (
      select 1 from public.sales_history
      where id = request_row.result_id and billar_id = p_billar_id
    ) then
      raise exception 'La venta registrada ya no está disponible.' using errcode = '55000';
    end if;
    return request_row.result_id;
  end if;

  perform 1 from public.products product
  where product.billar_id = p_billar_id and product.id in (
    select (item->>'product_id')::bigint
    from jsonb_array_elements(p_details) as items(item)
    where item->>'product_id' is not null
  )
  order by product.id for share;
  if exists (
    select 1 from jsonb_array_elements(p_details) as items(item)
    where item->>'product_id' is not null
      and not exists (
        select 1 from public.products product
        where product.id = (item->>'product_id')::bigint
          and product.billar_id = p_billar_id
      )
  ) then
    raise exception 'Un producto no está disponible en este billar.' using errcode = '42501';
  end if;

  if p_cloud_id is null then
    insert into public.sales_history (
      billar_id, total, paid, date, type, source_module, payment_method,
      cancelled, customer_key, sync_client_id
    ) values (
      p_billar_id, (p_sale->>'total')::double precision,
      (p_sale->>'paid')::double precision, p_sale->>'date', p_sale->>'type',
      p_sale->>'source_module', p_sale->>'payment_method',
      coalesce((p_sale->>'cancelled')::boolean, false), p_sale->>'customer_key',
      p_request_id
    )
    returning id into v_result_id;
  else
    update public.sales_history set
      total = (p_sale->>'total')::double precision,
      paid = (p_sale->>'paid')::double precision,
      date = p_sale->>'date', type = p_sale->>'type',
      source_module = p_sale->>'source_module',
      payment_method = p_sale->>'payment_method',
      cancelled = coalesce((p_sale->>'cancelled')::boolean, false),
      customer_key = p_sale->>'customer_key'
    where id = p_cloud_id and billar_id = p_billar_id
    returning id into v_result_id;
  end if;

  if v_result_id is null then
    raise exception 'La venta no está disponible en este billar.' using errcode = '42501';
  end if;
  delete from public.sale_details where sale_id = v_result_id;
  insert into public.sale_details (
    sale_id, product_id, product_name, quantity, price_at_sale, cost_at_sale, cancelled
  )
  select v_result_id, (item->>'product_id')::bigint, item->>'product_name',
    (item->>'quantity')::double precision, (item->>'price_at_sale')::double precision,
    coalesce((item->>'cost_at_sale')::numeric, 0),
    coalesce((p_sale->>'cancelled')::boolean, false)
  from jsonb_array_elements(p_details) as items(item);
  update public.owner_transaction_sync_requests
  set result_id = v_result_id, completed = true
  where request_id = p_request_id;
  return v_result_id;
end;
$$;

create or replace function public.sync_owner_purchase(
  p_request_id uuid,
  p_billar_id text,
  p_cloud_id bigint,
  p_purchase jsonb,
  p_details jsonb
)
returns bigint
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
declare
  actor uuid := auth.uid();
  v_result_id bigint;
  provider bigint;
  payload jsonb;
  request_row public.owner_transaction_sync_requests%rowtype;
  purchase_row public.purchases%rowtype;
  has_payment boolean;
  payment_fields text[] := array[
    'payment_condition', 'payment_method', 'credit_days', 'due_date', 'paid_amount', 'balance_due'
  ];
  field text;
  total_amount double precision;
  detail jsonb;
  detail_total numeric := 0;
begin
  if actor is null or p_request_id is null or p_billar_id is null
      or btrim(p_billar_id) = '' or jsonb_typeof(p_purchase) is distinct from 'object'
      or jsonb_typeof(p_details) is distinct from 'array' then
    raise exception 'Datos de sincronización inválidos.' using errcode = '22023';
  end if;
  perform 1 from public.billar_settings s
  join public.business_memberships m
    on m.user_id = s.user_id and m.billar_id = s.billar_id
  where s.user_id = actor and s.billar_id = p_billar_id
    and m.role = 'admin' and m.is_active and not m.must_change_password
  for share of s, m;
  if not found then
    raise exception 'Se requiere un administrador activo del billar.' using errcode = '42501';
  end if;
  payload := jsonb_build_object('cloud_id', p_cloud_id, 'purchase', p_purchase, 'details', p_details);
  insert into public.owner_transaction_sync_requests (
    request_id, actor_id, billar_id, kind, request_payload
  ) values (p_request_id, actor, p_billar_id, 'purchase', payload)
  on conflict (request_id) do nothing;
  select * into strict request_row
  from public.owner_transaction_sync_requests
  where request_id = p_request_id for update;
  if request_row.actor_id <> actor or request_row.billar_id <> p_billar_id
      or request_row.kind <> 'purchase' or request_row.request_payload <> payload then
    raise exception 'El identificador de sincronización ya fue utilizado.' using errcode = '23505';
  end if;
  if request_row.completed then
    if not exists (
      select 1 from public.purchases
      where id = request_row.result_id and billar_id = p_billar_id
    ) then
      raise exception 'La compra registrada ya no está disponible.' using errcode = '55000';
    end if;
    return request_row.result_id;
  end if;
  provider := (p_purchase->>'provider_id')::bigint;
  has_payment := p_purchase ?| payment_fields;
  if has_payment then
    if not (p_purchase ?& payment_fields)
       or jsonb_typeof(p_purchase -> 'payment_condition') is distinct from 'string'
       or p_purchase ->> 'payment_condition' not in ('contado', 'credito')
       or jsonb_typeof(p_purchase -> 'date') is distinct from 'string'
       or jsonb_typeof(p_purchase -> 'total') is distinct from 'number'
       or jsonb_typeof(p_purchase -> 'paid_amount') is distinct from 'number'
       or jsonb_typeof(p_purchase -> 'balance_due') is distinct from 'number' then
      raise exception 'Las condiciones de pago no son válidas.' using errcode = '22023';
    end if;
    total_amount := (p_purchase ->> 'total')::double precision;
    if (total_amount >= 0 and total_amount < 'Infinity'::double precision) is not true
       or not isfinite((p_purchase ->> 'date')::timestamptz) then
      raise exception 'El total de compra no es válido.' using errcode = '22023';
    end if;
    if jsonb_array_length(p_details) = 0 then
      raise exception 'La compra debe tener detalles.' using errcode = '22023';
    end if;
    for detail in select value from jsonb_array_elements(p_details) loop
      if jsonb_typeof(detail -> 'quantity') is distinct from 'number'
         or jsonb_typeof(detail -> 'cost_per_unit') is distinct from 'number' then
        raise exception 'El detalle de compra no es válido.' using errcode = '22023';
      end if;
      if (detail ->> 'quantity')::numeric <= 0 or (detail ->> 'cost_per_unit')::numeric < 0 then
        raise exception 'La cantidad o el costo no son válidos.' using errcode = '22023';
      end if;
      detail_total := detail_total + (detail ->> 'quantity')::numeric * (detail ->> 'cost_per_unit')::numeric;
    end loop;
    if abs(detail_total - total_amount::numeric) > greatest(0.000001, abs(total_amount::numeric) * 1e-10) then
      raise exception 'El total no coincide con los detalles.' using errcode = '22023';
    end if;
    if p_purchase ->> 'payment_condition' = 'credito' then
      if provider is null
         or jsonb_typeof(p_purchase -> 'payment_method') is distinct from 'null'
         or jsonb_typeof(p_purchase -> 'cash_source') is distinct from 'null'
         or jsonb_typeof(p_purchase -> 'credit_days') is distinct from 'number'
         or jsonb_typeof(p_purchase -> 'due_date') is distinct from 'string' then
        raise exception 'El crédito requiere proveedor, días y vencimiento, sin pago efectivo.' using errcode = '22023';
      end if;
      if ((p_purchase ->> 'credit_days')::numeric >= 0
          and (p_purchase ->> 'credit_days')::numeric <= 2147483647
          and (p_purchase ->> 'credit_days')::numeric = trunc((p_purchase ->> 'credit_days')::numeric)
          and (p_purchase ->> 'paid_amount')::double precision = 0
          and (p_purchase ->> 'balance_due')::double precision = total_amount) is not true then
        raise exception 'El crédito inicial debe ser total, sin anticipos.' using errcode = '22023';
      end if;
      if (p_purchase ->> 'due_date')::date > date '9999-12-31'
         or (p_purchase ->> 'due_date')::date is distinct from
           ((p_purchase ->> 'date')::timestamptz at time zone 'UTC')::date
             + (p_purchase ->> 'credit_days')::integer then
        raise exception 'El vencimiento no coincide con los días de crédito.' using errcode = '22023';
      end if;
    else
      if (jsonb_typeof(p_purchase -> 'credit_days') = 'null'
          and jsonb_typeof(p_purchase -> 'due_date') = 'null'
          and (p_purchase ->> 'paid_amount')::double precision = total_amount
          and (p_purchase ->> 'balance_due')::double precision = 0
          and ((p_purchase ->> 'payment_method' = 'efectivo'
                  and p_purchase ->> 'cash_source' in ('caja', 'cajero'))
            or (p_purchase ->> 'payment_method' in ('tarjeta', 'transferencia')
                  and p_purchase ->> 'cash_source' = p_purchase ->> 'payment_method'))) is not true then
        raise exception 'El pago de contado no es válido.' using errcode = '22023';
      end if;
    end if;
  end if;
  if provider is not null and not exists (
    select 1 from public.providers
    where id = provider and billar_id = p_billar_id
  ) then
    raise exception 'El proveedor no pertenece al billar.' using errcode = '42501';
  end if;
  if p_cloud_id is not null then
    select * into purchase_row from public.purchases
    where id = p_cloud_id and billar_id = p_billar_id for update;
    if not found then
      raise exception 'La compra no está disponible en este billar.' using errcode = '42501';
    end if;
    if purchase_row.payment_condition is not null then
      if not has_payment then
        raise exception 'Actualiza el cliente para conservar las condiciones de la compra.' using errcode = '22023';
      end if;
      foreach field in array payment_fields || array['provider_id', 'total', 'cash_source'] loop
        if to_jsonb(purchase_row) -> field is distinct from p_purchase -> field then
          raise exception 'Las condiciones registradas de la compra no se pueden cambiar.' using errcode = '22023';
        end if;
      end loop;
      if purchase_row.date::timestamptz is distinct from (p_purchase ->> 'date')::timestamptz then
        raise exception 'La fecha registrada de la compra no se puede cambiar.' using errcode = '22023';
      end if;
    elsif has_payment then
      raise exception 'No se pueden inventar condiciones de pago para una compra histórica.' using errcode = '22023';
    end if;
  end if;

  perform 1 from public.products product
  where product.billar_id = p_billar_id and product.id in (
    select (item->>'product_id')::bigint
    from jsonb_array_elements(p_details) as items(item)
    where item->>'product_id' is not null
  )
  order by product.id for share;
  if exists (
    select 1 from jsonb_array_elements(p_details) as items(item)
    where item->>'product_id' is null
      or not exists (
        select 1 from public.products product
        where product.id = (item->>'product_id')::bigint
          and product.billar_id = p_billar_id
      )
  ) then
    raise exception 'Un producto no está disponible en este billar.' using errcode = '42501';
  end if;

  if p_cloud_id is null then
    insert into public.purchases (
      billar_id, provider_id, total, date, reference, created_by, cash_source,
      cancelled, sync_client_id, payment_condition, payment_method,
      credit_days, due_date, paid_amount, balance_due
    ) values (
      p_billar_id, provider, (p_purchase->>'total')::double precision,
      p_purchase->>'date', p_purchase->>'reference', p_purchase->>'created_by',
      p_purchase->>'cash_source', coalesce((p_purchase->>'cancelled')::boolean, false),
      p_request_id, p_purchase ->> 'payment_condition', p_purchase ->> 'payment_method',
      (p_purchase ->> 'credit_days')::integer, (p_purchase ->> 'due_date')::date,
      (p_purchase ->> 'paid_amount')::double precision, (p_purchase ->> 'balance_due')::double precision
    )
    returning id into v_result_id;
  else
    update public.purchases set
      provider_id = provider, total = (p_purchase->>'total')::double precision,
      date = p_purchase->>'date', reference = p_purchase->>'reference',
      created_by = p_purchase->>'created_by', cash_source = p_purchase->>'cash_source',
      cancelled = coalesce((p_purchase->>'cancelled')::boolean, false)
    where id = p_cloud_id and billar_id = p_billar_id
    returning id into v_result_id;
  end if;

  if v_result_id is null then
    raise exception 'La compra no está disponible en este billar.' using errcode = '42501';
  end if;
  delete from public.purchase_details where purchase_id = v_result_id;
  insert into public.purchase_details (
    purchase_id, product_id, quantity, cost_per_unit, created_by, cancelled
  )
  select v_result_id, (item->>'product_id')::bigint,
    (item->>'quantity')::double precision, (item->>'cost_per_unit')::double precision,
    coalesce(item->>'created_by', p_purchase->>'created_by'),
    coalesce((p_purchase->>'cancelled')::boolean, false)
  from jsonb_array_elements(p_details) as items(item);
  update public.owner_transaction_sync_requests
  set result_id = v_result_id, completed = true
  where request_id = p_request_id;
  return v_result_id;
end;
$$;

-- A separate entry point prevents old servers from acknowledging a payload
-- while silently ignoring its new financial snapshot.
create or replace function public.sync_owner_purchase_with_payment(
  p_request_id uuid, p_billar_id text, p_cloud_id bigint,
  p_purchase jsonb, p_details jsonb
)
returns bigint
language plpgsql
security invoker
set search_path = pg_catalog, public, pg_temp
as $$
begin
  if jsonb_typeof(p_purchase) is distinct from 'object'
     or not (p_purchase ? 'payment_condition') then
    raise exception 'Se requieren condiciones de pago explícitas.' using errcode = '22023';
  end if;
  return public.sync_owner_purchase(p_request_id, p_billar_id, p_cloud_id, p_purchase, p_details);
end;
$$;

revoke all on function public.sync_owner_sale(uuid, text, bigint, jsonb, jsonb) from public, anon;
revoke all on function public.sync_owner_purchase(uuid, text, bigint, jsonb, jsonb) from public, anon;
revoke all on function public.sync_owner_purchase_with_payment(uuid, text, bigint, jsonb, jsonb) from public, anon;
grant execute on function public.sync_owner_sale(uuid, text, bigint, jsonb, jsonb) to authenticated;
grant execute on function public.sync_owner_purchase(uuid, text, bigint, jsonb, jsonb) to authenticated;
grant execute on function public.sync_owner_purchase_with_payment(uuid, text, bigint, jsonb, jsonb) to authenticated;

-- SOURCE: staff_account_creation_partial.sql
-- Partial preparation only. Do not deploy or enable staff accounts until
-- all POS permissions, online-only access and auditing have been completed.
-- Requires add_player_registration.sql and add_staff_account_fields.sql.


create table if not exists public.staff_account_audit (
    id bigint generated by default as identity primary key,
    billar_id text not null,
    actor_id uuid not null,
    target_user_id uuid not null,
    event_type text not null,
    details jsonb not null,
    created_at timestamptz not null default now()
);

alter table public.staff_account_audit enable row level security;
revoke all on public.staff_account_audit from public, anon, authenticated;
grant select on public.staff_account_audit to authenticated;
drop policy if exists staff_account_audit_admin_select on public.staff_account_audit;
create policy staff_account_audit_admin_select on public.staff_account_audit
for select to authenticated
using (public.has_billar_role(billar_id, array['admin']::text[]));

create table if not exists public.staff_account_requests (
    request_id uuid primary key,
    actor_id uuid not null,
    billar_id text not null,
    username text not null unique,
    full_name text not null,
    job_title text not null,
    allowed_modules text[] not null,
    email text not null,
    key_fingerprint text not null,
    user_id uuid,
    completed boolean not null default false,
    password_recovery_allowed boolean not null default true,
    created_at timestamptz not null default now()
);

alter table public.staff_account_requests
    add column if not exists password_recovery_allowed boolean not null default true;

alter table public.staff_account_requests enable row level security;
revoke all on public.staff_account_requests from public, anon, authenticated;

-- Membership changes must go through server-side operations rather than
-- directly through the client. Existing authenticated reads are unchanged.
alter table public.business_memberships
    add column if not exists staff_revision bigint not null default 0;
alter table public.business_memberships enable row level security;
drop policy if exists staff_membership_no_direct_insert on public.business_memberships;
create policy staff_membership_no_direct_insert on public.business_memberships
as restrictive for insert to authenticated with check (false);
drop policy if exists staff_membership_no_direct_update on public.business_memberships;
create policy staff_membership_no_direct_update on public.business_memberships
as restrictive for update to authenticated using (false) with check (false);
drop policy if exists staff_membership_no_direct_delete on public.business_memberships;
create policy staff_membership_no_direct_delete on public.business_memberships
as restrictive for delete to authenticated using (false);
revoke insert, update, delete on public.business_memberships from public, anon;

drop function if exists public.create_staff_membership(uuid, uuid, text, text, text, text, text[], text);

create or replace function public.reserve_staff_account(
    p_request_id uuid,
    p_actor_id uuid,
    p_billar_id text,
    p_username text,
    p_full_name text,
    p_job_title text,
    p_modules text[],
    p_email text,
    p_key_fingerprint text
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    expected_email text;
    request_row public.staff_account_requests%rowtype;
begin
    if p_request_id is null or p_actor_id is null
       or p_billar_id is null or btrim(p_billar_id) = ''
       or p_username is null or p_username !~ '^[a-z0-9][a-z0-9._-]{2,31}$'
       or p_full_name is null or length(btrim(p_full_name)) not between 1 and 120
       or p_job_title is null or length(btrim(p_job_title)) not between 1 and 80
       or p_modules is null or cardinality(p_modules) = 0
       or array_position(p_modules, null) is not null
       or not p_modules <@ array[
           'quick_sale', 'billiard_tables', 'dine_in', 'personal_account',
           'inventory', 'purchases', 'reports', 'players', 'settings'
       ]::text[]
       or p_key_fingerprint is null or p_key_fingerprint !~ '^[a-f0-9]{64}$' then
        raise exception 'Datos de personal inválidos.' using errcode = '22023';
    end if;

    perform 1 from public.business_memberships membership
    where membership.user_id = p_actor_id and membership.billar_id = p_billar_id
      and membership.is_active and not membership.must_change_password
      and membership.role = 'admin'
    for share;
    if not found then
        raise exception 'Solo un administrador activo puede crear personal.'
            using errcode = '42501';
    end if;

    expected_email := encode(convert_to(p_username, 'UTF8'), 'hex')
        || '@staff.baumar.invalid';
    if p_email is distinct from expected_email then
        raise exception 'Identificador de autenticación inválido.' using errcode = '22023';
    end if;
    insert into public.staff_account_requests (
        request_id, actor_id, billar_id, username, full_name, job_title,
        allowed_modules, email, key_fingerprint
    ) values (
        p_request_id, p_actor_id, p_billar_id, p_username, btrim(p_full_name), btrim(p_job_title),
        p_modules, p_email, p_key_fingerprint
    ) on conflict (request_id) do nothing;
    select * into strict request_row
    from public.staff_account_requests where request_id = p_request_id for update;
    if request_row.actor_id is distinct from p_actor_id
       or request_row.billar_id is distinct from p_billar_id
       or request_row.username is distinct from p_username
       or request_row.full_name is distinct from btrim(p_full_name)
       or request_row.job_title is distinct from btrim(p_job_title)
       or request_row.allowed_modules is distinct from p_modules
       or request_row.email is distinct from p_email
       or request_row.key_fingerprint is distinct from p_key_fingerprint then
        raise exception 'La solicitud ya fue utilizada con otros datos.' using errcode = '22023';
    end if;
    return jsonb_build_object('completed', request_row.completed);
end;
$$;

create or replace function public.find_staff_creation_auth_user(
    p_request_id uuid,
    p_actor_id uuid,
    p_billar_id text
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    request_row public.staff_account_requests%rowtype;
    auth_user auth.users%rowtype;
begin
    perform 1 from public.business_memberships membership
    where membership.user_id = p_actor_id and membership.billar_id = p_billar_id
      and membership.is_active and not membership.must_change_password and membership.role = 'admin'
    for share;
    if not found then
        raise exception 'Solo un administrador activo puede crear personal.' using errcode = '42501';
    end if;
    select * into request_row from public.staff_account_requests
    where request_id = p_request_id and actor_id = p_actor_id and billar_id = p_billar_id;
    if not found then
        raise exception 'La solicitud no está disponible.' using errcode = '42501';
    end if;
    select * into auth_user from auth.users where email = request_row.email;
    if not found then return null; end if;
    if auth_user.raw_app_meta_data->>'account_type' is distinct from 'staff'
       or auth_user.raw_app_meta_data->>'billar_id' is distinct from p_billar_id
       or auth_user.raw_app_meta_data->>'creation_request_id' is distinct from p_request_id::text then
        raise exception 'El usuario ya está registrado.' using errcode = '23505';
    end if;
    return auth_user.id;
end;
$$;

create or replace function public.finalize_staff_account(
    p_request_id uuid,
    p_actor_id uuid,
    p_billar_id text,
    p_user_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    request_row public.staff_account_requests%rowtype;
    staff_row public.business_memberships%rowtype;
begin
    perform 1 from public.business_memberships membership
    where membership.user_id = p_actor_id and membership.billar_id = p_billar_id
      and membership.is_active and not membership.must_change_password and membership.role = 'admin'
    for share;
    if not found then
        raise exception 'Solo un administrador activo puede crear personal.' using errcode = '42501';
    end if;
    select * into request_row from public.staff_account_requests
    where request_id = p_request_id and actor_id = p_actor_id and billar_id = p_billar_id
    for update;
    if not found then
        raise exception 'La solicitud no está disponible.' using errcode = '42501';
    end if;
    if p_user_id is null or p_user_id = p_actor_id
       or public.find_staff_creation_auth_user(p_request_id, p_actor_id, p_billar_id)
          is distinct from p_user_id then
        raise exception 'La cuenta de autenticación no coincide.' using errcode = '42501';
    end if;
    if request_row.completed then
        if request_row.user_id is distinct from p_user_id then
            raise exception 'La solicitud ya está vinculada a otra cuenta.' using errcode = '42501';
        end if;
    else
        insert into public.business_memberships (
            user_id, billar_id, email, role, is_active, must_change_password,
            created_by, username, full_name, job_title, allowed_modules
        ) values (
            p_user_id, p_billar_id, request_row.email, 'manager', true, true,
            p_actor_id, request_row.username, request_row.full_name, request_row.job_title,
            request_row.allowed_modules
        );
        insert into public.staff_account_audit (
            billar_id, actor_id, target_user_id, event_type, details
        ) values (
            p_billar_id, p_actor_id, p_user_id, 'create',
            jsonb_build_object('username', request_row.username, 'modules', to_jsonb(request_row.allowed_modules))
        );
        update public.staff_account_requests
        set user_id = p_user_id, completed = true where request_id = p_request_id;
    end if;
    select * into staff_row from public.business_memberships
    where user_id = p_user_id and billar_id = p_billar_id;
    if not found then
        raise exception 'La cuenta ya no está disponible.' using errcode = '42501';
    end if;
    return jsonb_build_object(
        'user_id', p_user_id,
        'billar_id', p_billar_id,
        'username', staff_row.username,
        'full_name', staff_row.full_name,
        'job_title', staff_row.job_title,
        'allowed_modules', to_jsonb(staff_row.allowed_modules),
        'is_active', staff_row.is_active,
        'staff_revision', staff_row.staff_revision,
        'must_change_password', staff_row.must_change_password,
        'can_deliver_password', request_row.password_recovery_allowed
            and staff_row.is_active and staff_row.must_change_password
            and staff_row.role = 'manager' and staff_row.username = request_row.username
    );
end;
$$;

create or replace function public.stop_staff_password_recovery(p_user_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
    update public.staff_account_requests
    set password_recovery_allowed = false
    where user_id = p_user_id and completed;
    return found;
end;
$$;

create or replace function public.complete_staff_password_change(
    p_user_id uuid, p_billar_id text, p_expected_revision bigint
)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    staff public.business_memberships%rowtype;
begin
    if p_user_id is null or p_billar_id is null or btrim(p_billar_id) = ''
       or p_expected_revision is null or p_expected_revision < 0 then
        raise exception 'La cuenta o revisión de personal no es válida.' using errcode = '22023';
    end if;
    select * into staff from public.business_memberships membership
    where membership.user_id = p_user_id and membership.billar_id = p_billar_id
    for update;
    if not found or not staff.is_active or staff.role <> 'manager'
       or staff.username is null or not exists (
           select 1 from auth.users account where account.id = p_user_id
             and account.raw_app_meta_data ->> 'account_type' = 'staff'
             and account.raw_app_meta_data ->> 'billar_id' = p_billar_id
       ) then
        raise exception 'La cuenta de personal ya no tiene acceso activo.' using errcode = '42501';
    end if;
    if not staff.must_change_password and staff.staff_revision = p_expected_revision + 1 then
        return true;
    end if;
    if staff.staff_revision <> p_expected_revision or not staff.must_change_password then
        raise exception 'La cuenta cambió durante el cambio de contraseña.' using errcode = '40001';
    end if;
    if not exists (
        select 1 from public.staff_account_requests request
        where request.user_id = p_user_id and request.completed
          and not request.password_recovery_allowed
    ) or exists (
        select 1 from public.staff_account_requests request
        where request.user_id = p_user_id and request.completed
          and request.password_recovery_allowed
    ) then
        raise exception 'No se aseguró el cambio de contraseña.' using errcode = '55000';
    end if;
    update public.business_memberships
    set must_change_password = false, staff_revision = staff_revision + 1
    where user_id = p_user_id and billar_id = p_billar_id;
    insert into public.staff_account_audit (
        billar_id, actor_id, target_user_id, event_type, details
    ) values (
        p_billar_id, p_user_id, p_user_id, 'password_changed',
        jsonb_build_object('staff_revision', staff.staff_revision + 1)
    );
    return true;
end;
$$;

create or replace function public.list_staff_accounts(p_billar_id text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    result jsonb;
begin
    perform 1 from public.business_memberships membership
    where membership.user_id = auth.uid() and membership.billar_id = p_billar_id
      and membership.is_active and not membership.must_change_password
      and membership.role = 'admin'
    for share;
    if not found then
        raise exception 'Solo un administrador activo puede consultar personal.'
            using errcode = '42501';
    end if;
    select coalesce(jsonb_agg(jsonb_build_object(
        'user_id', staff.user_id, 'billar_id', staff.billar_id,
        'username', staff.username, 'full_name', staff.full_name,
        'job_title', staff.job_title, 'allowed_modules', to_jsonb(staff.allowed_modules),
        'is_active', staff.is_active, 'must_change_password', staff.must_change_password,
        'staff_revision', staff.staff_revision
    ) order by staff.full_name, staff.username), '[]'::jsonb) into result
    from public.business_memberships staff
    where staff.billar_id = p_billar_id and staff.role = 'manager'
      and staff.username is not null;
    return result;
end;
$$;

drop function if exists public.update_staff_account(uuid, text, uuid, text, text, text[], boolean);
create or replace function public.update_staff_account(
    p_actor_id uuid,
    p_billar_id text,
    p_user_id uuid,
    p_full_name text,
    p_job_title text,
    p_modules text[],
    p_is_active boolean,
    p_expected_revision bigint
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    staff_row public.business_memberships%rowtype;
    normalized_modules text[];
    previous jsonb;
begin
    if p_actor_id is null or p_user_id is null or p_actor_id = p_user_id
       or p_billar_id is null or btrim(p_billar_id) = ''
       or p_full_name is null or length(btrim(p_full_name)) not between 1 and 120
       or p_job_title is null or length(btrim(p_job_title)) not between 1 and 80
       or p_modules is null or cardinality(p_modules) = 0
       or array_position(p_modules, null) is not null
       or not p_modules <@ array[
           'quick_sale', 'billiard_tables', 'dine_in', 'personal_account',
           'inventory', 'purchases', 'reports', 'players', 'settings'
       ]::text[]
       or p_is_active is null or p_expected_revision is null or p_expected_revision < 0 then
        raise exception 'Datos de personal inválidos.' using errcode = '22023';
    end if;

    perform 1 from public.business_memberships membership
    where membership.user_id = p_actor_id and membership.billar_id = p_billar_id
      and membership.is_active and not membership.must_change_password
      and membership.role = 'admin'
    for share;
    if not found then
        raise exception 'Solo un administrador activo puede gestionar personal.'
            using errcode = '42501';
    end if;

    select * into staff_row from public.business_memberships
    where user_id = p_user_id and billar_id = p_billar_id
      and role = 'manager' and username is not null
    for update;
    if not found then
        raise exception 'No se encontró la cuenta de personal.' using errcode = '42501';
    end if;
    select array_agg(distinct module order by module) into normalized_modules
    from unnest(p_modules) module;

    if staff_row.full_name is distinct from btrim(p_full_name)
       or staff_row.job_title is distinct from btrim(p_job_title)
       or (select array_agg(distinct module order by module)
           from unnest(staff_row.allowed_modules) module) is distinct from normalized_modules
       or staff_row.is_active is distinct from p_is_active then
        if staff_row.staff_revision <> p_expected_revision then
            raise exception 'La cuenta cambió. Actualiza la información antes de modificarla.'
                using errcode = '40001';
        end if;
        previous := jsonb_build_object(
            'full_name', staff_row.full_name, 'job_title', staff_row.job_title,
            'modules', to_jsonb(staff_row.allowed_modules), 'is_active', staff_row.is_active
        );
        update public.business_memberships
        set full_name = btrim(p_full_name),
            job_title = btrim(p_job_title),
            allowed_modules = normalized_modules,
            is_active = p_is_active,
            staff_revision = staff_revision + 1
        where user_id = p_user_id and billar_id = p_billar_id
        returning * into staff_row;

        insert into public.staff_account_audit (
            billar_id, actor_id, target_user_id, event_type, details
        ) values (
            p_billar_id, p_actor_id, p_user_id, 'update',
            jsonb_build_object(
                'before', previous,
                'after', jsonb_build_object(
                    'full_name', staff_row.full_name, 'job_title', staff_row.job_title,
                    'modules', to_jsonb(staff_row.allowed_modules), 'is_active', staff_row.is_active
                )
            )
        );
    end if;
    return jsonb_build_object(
        'user_id', staff_row.user_id, 'billar_id', staff_row.billar_id,
        'username', staff_row.username, 'full_name', staff_row.full_name,
        'job_title', staff_row.job_title, 'allowed_modules', to_jsonb(staff_row.allowed_modules),
        'is_active', staff_row.is_active, 'must_change_password', staff_row.must_change_password,
        'staff_revision', staff_row.staff_revision
    );
end;
$$;

revoke all on function public.reserve_staff_account(uuid, uuid, text, text, text, text, text[], text, text)
