create or replace function public.record_staff_sale(
    p_request_id uuid,
    p_billar_id text,
    p_source_module text,
    p_sale_type text,
    p_sale_date text,
    p_payment_method text,
    p_total double precision,
    p_paid double precision,
    p_customer_key text,
    p_items jsonb
)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    actor uuid := auth.uid();
    request_payload jsonb;
    request_row public.staff_sale_requests%rowtype;
    new_sale_id bigint;
    item jsonb;
    item_product_id bigint;
    item_cost double precision;
    item_quantity numeric;
    item_price numeric;
    calculated_total numeric := 0;
    allow_negative boolean;
    product_row public.products%rowtype;
    component record;
    component_count integer;
    stock_quantity double precision;
begin
    if actor is null then
        raise exception 'Se requiere una sesión autenticada.' using errcode = '42501';
    end if;
    if p_request_id is null or p_billar_id is null or btrim(p_billar_id) = ''
       or p_source_module is null or p_source_module not in
           ('quick_sale', 'billiard_tables', 'dine_in', 'personal_account')
       or p_sale_type is null or btrim(p_sale_type) = ''
       or p_sale_date is null or btrim(p_sale_date) = ''
       or p_payment_method is null or btrim(p_payment_method) = ''
       or (p_total >= 0 and p_total < 'Infinity'::double precision) is not true
       or (p_paid >= 0 and p_paid < 'Infinity'::double precision) is not true
       or p_items is null or jsonb_typeof(p_items) <> 'array' then
        raise exception 'Datos de venta inválidos.' using errcode = '22023';
    end if;
    if jsonb_array_length(p_items) = 0 then
        raise exception 'La venta debe tener al menos un detalle.' using errcode = '22023';
    end if;
    if p_source_module <> 'quick_sale' or p_sale_type <> 'Venta Rápida'
       or p_customer_key is not null then
        raise exception 'Este módulo de venta aún no está habilitado.' using errcode = '42501';
    end if;

    perform 1
    from public.business_memberships membership
    where membership.user_id = actor
      and membership.billar_id = p_billar_id
      and membership.is_active
      and not membership.must_change_password
      and membership.role = 'manager'
      and membership.username is not null
      and p_source_module = any (membership.allowed_modules)
    for share;
    if not found then
        raise exception 'No tienes permiso para registrar esta venta.' using errcode = '42501';
    end if;

    request_payload := jsonb_build_object(
        'source_module', p_source_module, 'sale_type', p_sale_type,
        'sale_date', p_sale_date, 'payment_method', p_payment_method,
        'total', p_total, 'paid', p_paid, 'customer_key', p_customer_key,
        'items', p_items
    );
    insert into public.staff_sale_requests (billar_id, request_id, actor_id, request_payload)
    values (p_billar_id, p_request_id, actor, request_payload)
    on conflict (billar_id, request_id) do nothing;

    select * into strict request_row
    from public.staff_sale_requests
    where billar_id = p_billar_id and request_id = p_request_id
    for update;
    if request_row.actor_id <> actor or request_row.request_payload <> request_payload then
        raise exception 'El identificador de venta ya fue utilizado.' using errcode = '23505';
    end if;
    if request_row.completed then
        if not exists (select 1 from public.sales_history sale where sale.id = request_row.sale_id) then
            raise exception 'La venta registrada ya no está disponible.' using errcode = '55000';
        end if;
        return request_row.sale_id;
    end if;

    if (select count(*) from public.billar_settings where billar_id = p_billar_id) <> 1 then
        raise exception 'No hay una configuración única para este billar.' using errcode = '55000';
    end if;
    select settings.allow_negative_stock_sales into strict allow_negative
    from public.billar_settings settings
    where settings.billar_id = p_billar_id;

    insert into public.sales_history (
        billar_id, type, source_module, date, payment_method, total, paid, customer_key, cancelled
    ) values (
        p_billar_id, p_sale_type, p_source_module, p_sale_date, p_payment_method,
        p_total, p_paid, p_customer_key, false
    ) returning id into new_sale_id;

    for item in select value from jsonb_array_elements(p_items)
    loop
        if jsonb_typeof(item) <> 'object'
           or jsonb_typeof(item -> 'product_name') is distinct from 'string'
           or btrim(item ->> 'product_name') = ''
           or jsonb_typeof(item -> 'quantity') is distinct from 'number'
           or jsonb_typeof(item -> 'price_at_sale') is distinct from 'number' then
            raise exception 'Detalle de venta inválido.' using errcode = '22023';
        end if;
        item_quantity := (item ->> 'quantity')::numeric;
        item_price := (item ->> 'price_at_sale')::numeric;
        if item_quantity <= 0 or item_price < 0 then
            raise exception 'Cantidad o precio inválido.' using errcode = '22023';
        end if;
        calculated_total := calculated_total + item_quantity * item_price;

        if jsonb_typeof(item -> 'product_id') is distinct from 'number'
           or (item ->> 'product_id')::numeric <> trunc((item ->> 'product_id')::numeric) then
            raise exception 'Producto inválido.' using errcode = '22023';
        end if;
        item_product_id := (item ->> 'product_id')::bigint;
        select * into product_row from public.products product
        where product.id = item_product_id and product.billar_id = p_billar_id
          and product.is_active
        for update;
        if not found then
            raise exception 'El producto no pertenece a este billar o no está activo.'
                using errcode = '42501';
        end if;
        if abs(item_price - product_row.price::numeric) > 0.000001 then
            raise exception 'El precio del producto cambió; actualiza el inventario.'
                using errcode = '22023';
        end if;
        item_cost := coalesce(product_row.cost, 0);

        if product_row.parent_id is not null then
            if product_row.pieces_per_unit <= 0 then
                raise exception 'La presentación del producto es inválida.' using errcode = '22023';
            end if;
            stock_quantity := (item_quantity * product_row.pieces_per_unit)::double precision;
            update public.products
            set stock = stock - stock_quantity, stock_revision = stock_revision + 1
            where id = product_row.parent_id and billar_id = p_billar_id
              and parent_id is null and is_promo = 0 and is_active
              and (allow_negative or stock >= stock_quantity);
            if not found then
                raise exception 'No hay existencias suficientes o el producto padre es inválido.'
                    using errcode = '22023';
            end if;
            insert into public.staff_sale_stock_products (billar_id, request_id, product_id)
            values (p_billar_id, p_request_id, product_row.parent_id)
            on conflict do nothing;
        elsif product_row.is_promo = 1 then
            component_count := 0;
            for component in
                select child_id, quantity from public.promo_items
                where parent_id = item_product_id
                order by child_id
                for share
            loop
                component_count := component_count + 1;
                if component.quantity <= 0 then
                    raise exception 'La promoción contiene cantidades inválidas.' using errcode = '22023';
                end if;
                stock_quantity := (item_quantity * component.quantity)::double precision;
                update public.products
                set stock = stock - stock_quantity, stock_revision = stock_revision + 1
                where id = component.child_id and billar_id = p_billar_id
                  and parent_id is null and is_promo = 0 and is_active
                  and (allow_negative or stock >= stock_quantity);
                if not found then
                    raise exception 'No hay existencias suficientes para la promoción.'
                        using errcode = '22023';
                end if;
                insert into public.staff_sale_stock_products (billar_id, request_id, product_id)
                values (p_billar_id, p_request_id, component.child_id)
                on conflict do nothing;
            end loop;
            if component_count = 0 then
                raise exception 'La promoción no tiene componentes.' using errcode = '22023';
            end if;
        else
            stock_quantity := item_quantity::double precision;
            update public.products
            set stock = stock - stock_quantity, stock_revision = stock_revision + 1
            where id = item_product_id and billar_id = p_billar_id
              and (allow_negative or stock >= stock_quantity);
            if not found then
                raise exception 'No hay existencias suficientes.' using errcode = '22023';
            end if;
            insert into public.staff_sale_stock_products (billar_id, request_id, product_id)
            values (p_billar_id, p_request_id, item_product_id)
            on conflict do nothing;
        end if;

        insert into public.sale_details (
            sale_id, product_id, product_name, quantity, price_at_sale, cost_at_sale, cancelled
        ) values (
            new_sale_id, item_product_id, product_row.name,
            item_quantity::double precision, item_price::double precision, item_cost, false
        );
        insert into public.inventory_movements (
            billar_id, product_id, movement_type, quantity, unit_cost,
            unit_price, reference_id, reference_type, notes
        ) values (
            p_billar_id, item_product_id, 'sale', -item_quantity::double precision,
            item_cost, item_price::double precision, new_sale_id, 'sales_history', 'Venta rápida'
        );
    end loop;

    if abs(calculated_total - p_total::numeric)
       > greatest(0.000001::numeric, abs(calculated_total) * 0.0000000001::numeric) then
        raise exception 'El total no coincide con los detalles.' using errcode = '22023';
    end if;

    insert into public.staff_sale_audit (billar_id, actor_id, sale_id)
    values (p_billar_id, actor, new_sale_id);
    update public.staff_sale_requests
    set sale_id = new_sale_id, completed = true
    where billar_id = p_billar_id and request_id = p_request_id;
    return new_sale_id;
end;
$$;

revoke all on function public.record_staff_sale(
    uuid, text, text, text, text, text, double precision, double precision, text, jsonb
) from public, anon, authenticated;

create or replace function public.get_staff_sale_reconciliation(
    p_request_id uuid,
    p_billar_id text
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    result jsonb;
    may_view_cost boolean;
begin
    if auth.uid() is null or p_request_id is null or p_billar_id is null
       or btrim(p_billar_id) = '' then
        raise exception 'Datos de recuperación inválidos.' using errcode = '42501';
    end if;
    perform 1 from public.business_memberships membership
    where membership.user_id = auth.uid()
      and membership.billar_id = p_billar_id
      and membership.is_active and not membership.must_change_password
      and membership.role = 'manager' and membership.username is not null
      and 'quick_sale' = any(membership.allowed_modules)
    for share;
    if not found then
        raise exception 'No tienes permiso para recuperar esta venta.' using errcode = '42501';
    end if;
    select 'reports' = any(membership.allowed_modules) into strict may_view_cost
    from public.business_memberships membership
    where membership.user_id = auth.uid() and membership.billar_id = p_billar_id
      and membership.is_active and not membership.must_change_password
      and membership.role = 'manager' and membership.username is not null
      and 'quick_sale' = any(membership.allowed_modules);
    select jsonb_build_object(
        'request_id', request.request_id,
        'billar_id', request.billar_id,
        'sale_id', sale.id,
        'date', sale.date,
        'payment_method', sale.payment_method,
        'total', sale.total,
        'paid', sale.paid,
        'cancelled', sale.cancelled,
        'items', (
            select coalesce(jsonb_agg((jsonb_build_object(
                'product_id', detail.product_id, 'product_name', detail.product_name,
                'quantity', detail.quantity, 'price_at_sale', detail.price_at_sale,
                'cancelled', detail.cancelled
            ) || case when may_view_cost then
                jsonb_build_object('cost_at_sale', detail.cost_at_sale)
                else '{}'::jsonb end) order by detail.id), '[]'::jsonb)
            from public.sale_details detail where detail.sale_id = sale.id
        ),
        'stock', (
            select coalesce(jsonb_agg(jsonb_build_object(
                'product_id', product.id, 'stock', product.stock,
                'stock_revision', product.stock_revision
            ) order by product.id), '[]'::jsonb)
            from public.staff_sale_stock_products changed
            join public.products product on product.id = changed.product_id
                and product.billar_id = changed.billar_id
            where changed.billar_id = request.billar_id
                and changed.request_id = request.request_id
        )
    ) into result
    from public.staff_sale_requests request
    join public.sales_history sale on sale.id = request.sale_id
        and sale.billar_id = request.billar_id
    where request.billar_id = p_billar_id and request.request_id = p_request_id
      and request.actor_id = auth.uid() and request.completed;
    if result is null or jsonb_array_length(result -> 'items') = 0
       or jsonb_array_length(result -> 'stock') = 0
       or jsonb_array_length(result -> 'stock') <> (
           select count(*) from public.staff_sale_stock_products changed
           where changed.billar_id = p_billar_id and changed.request_id = p_request_id
       ) then
        raise exception 'No se encontró una venta recuperable.' using errcode = '55000';
    end if;
    return result;
end;
$$;
revoke all on function public.get_staff_sale_reconciliation(uuid, text)
    from public, anon, authenticated;

-- SOURCE: staff_provider_operations_partial.sql
-- Preparation only: do not deploy or enable staff purchases yet.
-- Requires staff account fields, staff_purchases_guards_partial.sql and
-- provider_delete_idempotent_partial.sql and provider_credit_terms_partial.sql.
-- No execution grants are enabled.
-- The client must persist the UUID, provider ID and exact payload before sending.

set local lock_timeout = '3s';
set local statement_timeout = '30s';

create table if not exists public.staff_provider_requests (
    request_id uuid primary key,
    billar_id text not null,
    actor_id uuid not null,
    request_payload jsonb not null,
    result jsonb
);
alter table public.staff_provider_requests enable row level security;
revoke all on public.staff_provider_requests from public, anon, authenticated;

create table if not exists public.staff_provider_audit (
    request_id uuid primary key references public.staff_provider_requests(request_id),
    billar_id text not null,
    actor_id uuid not null,
    provider_id bigint not null,
    operation text not null check (operation in ('create', 'update', 'archive')),
    old_values jsonb,
    new_values jsonb not null,
    recorded_at timestamptz not null default clock_timestamp()
);
alter table public.staff_provider_audit enable row level security;
revoke all on public.staff_provider_audit from public, anon, authenticated;
grant select on public.staff_provider_audit to authenticated;
drop policy if exists staff_provider_audit_admin_select on public.staff_provider_audit;
create policy staff_provider_audit_admin_select on public.staff_provider_audit
for select to authenticated
using (public.has_billar_role(billar_id, array['admin']::text[]));

create or replace function public.apply_staff_provider_operation(
    p_request_id uuid,
    p_billar_id text,
    p_provider_id bigint,
    p_operation text,
    p_provider jsonb,
    p_product_ids bigint[]
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
declare
    actor uuid := auth.uid();
    metadata jsonb := auth.jwt() -> 'app_metadata';
    payload jsonb;
    request_row public.staff_provider_requests%rowtype;
    provider_row public.providers%rowtype;
    previous_values jsonb;
    current_values jsonb;
    receipt jsonb;
    field text;
begin
    if actor is null or metadata ->> 'account_type' is distinct from 'staff'
       or metadata ->> 'billar_id' is distinct from p_billar_id then
        raise exception 'Se requiere una cuenta de personal de este billar.'
            using errcode = '42501';
    end if;
    if p_request_id is null or p_billar_id is null or btrim(p_billar_id) = ''
       or p_provider_id is null or p_provider_id <= 0
       or p_operation is null or p_operation not in ('create', 'update', 'archive')
       or jsonb_typeof(p_provider) is distinct from 'object'
       or p_product_ids is null then
        raise exception 'La operación de proveedor no es válida.' using errcode = '22023';
    end if;
    if exists (select 1 from unnest(p_product_ids) requested(id) where requested.id is null or requested.id <= 0)
       or cardinality(p_product_ids) <> (select count(distinct requested.id) from unnest(p_product_ids) requested(id))
       or (cardinality(p_product_ids) > 0 and array_ndims(p_product_ids) <> 1) then
        raise exception 'La lista de productos no es válida.' using errcode = '22023';
    end if;
    if p_operation = 'archive' then
        if p_provider <> '{}'::jsonb or cardinality(p_product_ids) <> 0 then
            raise exception 'El archivado no admite cambios adicionales.' using errcode = '22023';
        end if;
    else
        if (select count(*) from jsonb_object_keys(p_provider)) not in (8, 10) then
            raise exception 'Los datos del proveedor no están completos.' using errcode = '22023';
        end if;
        foreach field in array array[
            'name', 'phone', 'email', 'address', 'contact_name', 'notes', 'category', 'visit_days'
        ] loop
            if jsonb_typeof(p_provider -> field) is distinct from 'string' then
                raise exception 'Los datos del proveedor no son válidos.' using errcode = '22023';
            end if;
        end loop;
        if btrim(p_provider ->> 'name') = '' then
            raise exception 'El nombre del proveedor es obligatorio.' using errcode = '22023';
        end if;
        if (select count(*) from jsonb_object_keys(p_provider)) = 10 then
            if not (p_provider ?& array['credit_days', 'preferred_payment_method'])
               or jsonb_typeof(p_provider -> 'credit_days') not in ('null', 'number')
               or jsonb_typeof(p_provider -> 'preferred_payment_method') not in ('null', 'string') then
                raise exception 'Las condiciones de pago del proveedor no son válidas.' using errcode = '22023';
            end if;
            if jsonb_typeof(p_provider -> 'credit_days') = 'number' then
                if (p_provider ->> 'credit_days')::numeric < 0
                   or (p_provider ->> 'credit_days')::numeric > 2147483647
                   or (p_provider ->> 'credit_days')::numeric <> trunc((p_provider ->> 'credit_days')::numeric) then
                    raise exception 'Los días de crédito no son válidos.' using errcode = '22023';
                end if;
            end if;
            if jsonb_typeof(p_provider -> 'preferred_payment_method') = 'string'
               and p_provider ->> 'preferred_payment_method' not in ('efectivo', 'tarjeta', 'transferencia', 'credito') then
                raise exception 'La preferencia de pago no es válida.' using errcode = '22023';
            end if;
        end if;
    end if;

    perform 1 from public.business_memberships membership
    where membership.user_id = actor and membership.billar_id = p_billar_id
      and membership.role = 'manager' and membership.is_active
      and not membership.must_change_password
      and membership.username is not null and btrim(membership.username) <> ''
      and 'purchases' = any(membership.allowed_modules)
    for share;
    if not found then
        raise exception 'No tienes permiso para gestionar proveedores.' using errcode = '42501';
    end if;

    payload := jsonb_build_object(
        'provider_id', p_provider_id, 'operation', p_operation,
        'provider', p_provider, 'product_ids', to_jsonb(p_product_ids)
    );
    insert into public.staff_provider_requests(request_id, billar_id, actor_id, request_payload)
    values (p_request_id, p_billar_id, actor, payload)
    on conflict (request_id) do nothing;
    select * into strict request_row from public.staff_provider_requests
    where request_id = p_request_id for update;
    if request_row.billar_id <> p_billar_id or request_row.actor_id <> actor
       or request_row.request_payload <> payload then
        raise exception 'El identificador de solicitud ya fue utilizado.' using errcode = '23505';
    end if;
    if request_row.result is not null then return request_row.result; end if;

    select * into provider_row from public.providers
    where id = p_provider_id for update;
    if p_operation = 'create' then
        if found then
            raise exception 'El identificador de proveedor ya existe.' using errcode = '23505';
        end if;
    else
        if not found or provider_row.billar_id <> p_billar_id or not provider_row.is_active then
            raise exception 'El proveedor no está activo en este billar.' using errcode = '42501';
        end if;
        previous_values := jsonb_build_object(
            'provider', to_jsonb(provider_row),
            'product_ids', (select coalesce(jsonb_agg(product_id order by product_id), '[]'::jsonb)
                from public.provider_products where provider_id = p_provider_id)
        );
    end if;

    perform 1 from public.products product
    where product.billar_id = p_billar_id and product.id = any(p_product_ids)
    order by product.id for share;
    if exists (
        select 1 from unnest(p_product_ids) requested(id) where not exists (
            select 1 from public.products product where product.id = requested.id
              and product.billar_id = p_billar_id
        )
    ) then
        raise exception 'Un producto no pertenece a este billar.' using errcode = '42501';
    end if;

    if p_operation = 'create' then
        insert into public.providers (
            id, billar_id, name, phone, email, address, contact_name, notes, category, visit_days,
            credit_days, preferred_payment_method, is_active
        ) values (
            p_provider_id, p_billar_id, p_provider ->> 'name', p_provider ->> 'phone',
            p_provider ->> 'email', p_provider ->> 'address', p_provider ->> 'contact_name',
            p_provider ->> 'notes', p_provider ->> 'category', p_provider ->> 'visit_days',
            (p_provider ->> 'credit_days')::integer, p_provider ->> 'preferred_payment_method', true
        );
    elsif p_operation = 'update' then
        update public.providers set
            name = p_provider ->> 'name', phone = p_provider ->> 'phone',
            email = p_provider ->> 'email', address = p_provider ->> 'address',
            contact_name = p_provider ->> 'contact_name', notes = p_provider ->> 'notes',
            category = p_provider ->> 'category', visit_days = p_provider ->> 'visit_days',
            credit_days = case when p_provider ? 'credit_days'
                then (p_provider ->> 'credit_days')::integer else provider_row.credit_days end,
            preferred_payment_method = case when p_provider ? 'preferred_payment_method'
                then p_provider ->> 'preferred_payment_method' else provider_row.preferred_payment_method end
        where id = p_provider_id and billar_id = p_billar_id;
    else
        update public.providers set is_active = false
        where id = p_provider_id and billar_id = p_billar_id;
    end if;
    if p_operation <> 'archive' then
        delete from public.provider_products where provider_id = p_provider_id;
        insert into public.provider_products(provider_id, product_id)
        select p_provider_id, requested.id from unnest(p_product_ids) requested(id);
    end if;
    select * into strict provider_row from public.providers
    where id = p_provider_id and billar_id = p_billar_id;
    current_values := jsonb_build_object(
        'provider', to_jsonb(provider_row),
        'product_ids', (select coalesce(jsonb_agg(product_id order by product_id), '[]'::jsonb)
            from public.provider_products where provider_id = p_provider_id)
    );
    insert into public.staff_provider_audit (
        request_id, billar_id, actor_id, provider_id, operation, old_values, new_values
    ) values (
        p_request_id, p_billar_id, actor, p_provider_id, p_operation, previous_values, current_values
    );
    receipt := jsonb_build_object(
        'request_id', p_request_id, 'billar_id', p_billar_id, 'actor_id', actor,
        'provider_id', p_provider_id, 'operation', p_operation,
        'provider', current_values -> 'provider', 'product_ids', current_values -> 'product_ids'
    );
    update public.staff_provider_requests set result = receipt where request_id = p_request_id;
    return receipt;
end;
$$;
revoke all on function public.apply_staff_provider_operation(uuid, text, bigint, text, jsonb, bigint[])
from public, anon, authenticated;

-- SOURCE: staff_purchase_recording_partial.sql
-- Preparation only. Do not deploy or enable staff purchases yet.
-- Requires staff account fields, purchase/provider columns, staff purchase and
-- inventory guards, product_stock_conflict_guard_partial.sql and
-- purchase_payment_terms_partial.sql.
-- Items preserve the presentation the user confirmed; names, date and totals
-- are authoritative server values. Execution remains revoked.

set local lock_timeout = '3s';
set local statement_timeout = '30s';

create table if not exists public.staff_purchase_requests (
    request_id uuid primary key,
    billar_id text not null,
    actor_id uuid not null,
    request_payload jsonb not null,
    result jsonb
);
alter table public.staff_purchase_requests enable row level security;
revoke all on public.staff_purchase_requests from public, anon, authenticated;

create table if not exists public.staff_purchase_audit (
    request_id uuid primary key references public.staff_purchase_requests(request_id),
    billar_id text not null,
    actor_id uuid not null,
    purchase_id bigint not null references public.purchases(id),
    receipt jsonb not null,
    recorded_at timestamptz not null default clock_timestamp()
);
alter table public.staff_purchase_audit enable row level security;
revoke all on public.staff_purchase_audit from public, anon, authenticated;
grant select on public.staff_purchase_audit to authenticated;
drop policy if exists staff_purchase_audit_admin_select on public.staff_purchase_audit;
create policy staff_purchase_audit_admin_select on public.staff_purchase_audit
for select to authenticated
using (public.has_billar_role(billar_id, array['admin']::text[]));

create or replace function public.record_staff_purchase(
    p_request_id uuid,
    p_billar_id text,
    p_provider_id bigint,
    p_reference text,
    p_cash_source text,
    p_items jsonb,
    p_payment jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
declare
    actor uuid := auth.uid();
    metadata jsonb := auth.jwt() -> 'app_metadata';
    uploader text;
    payload jsonb;
    request_row public.staff_purchase_requests%rowtype;
    item jsonb;
    product_row public.products%rowtype;
    base public.products%rowtype;
    requested_ids bigint[] := '{}';
    target_ids bigint[] := '{}';
    locked_ids bigint[];
    product_id bigint;
    parent bigint;
    pieces integer;
    quantity numeric;
    unit_cost numeric;
    stock_quantity double precision;
    cost_per_piece double precision;
    total numeric := 0;
    purchase_id bigint;
    purchase_date text;
    original_stock jsonb;
    details jsonb := '[]'::jsonb;
    receipt jsonb;
    payment_option text;
    payment_days integer;
    maturity date;
begin
    if actor is null or metadata ->> 'account_type' is distinct from 'staff'
       or metadata ->> 'billar_id' is distinct from p_billar_id then
        raise exception 'Se requiere una cuenta de personal de este billar.' using errcode = '42501';
    end if;
    if p_request_id is null or p_billar_id is null or btrim(p_billar_id) = ''
       or (p_provider_id is not null and p_provider_id <= 0)
       or p_reference is null
       or (p_payment is null and (p_cash_source is null
           or p_cash_source not in ('caja', 'cajero', 'transferencia', 'tarjeta')))
       or jsonb_typeof(p_items) is distinct from 'array' then
        raise exception 'Los datos de compra no son válidos.' using errcode = '22023';
    end if;
    if jsonb_array_length(p_items) = 0 then
        raise exception 'La compra debe tener al menos un detalle.' using errcode = '22023';
    end if;
    if p_payment is not null then
        if jsonb_typeof(p_payment) is distinct from 'object' then
            raise exception 'Las condiciones de la compra no son válidas.' using errcode = '22023';
        end if;
        if (select count(*) from jsonb_object_keys(p_payment)) <> 3
           or not (p_payment ?& array['option', 'cash_source', 'credit_days'])
           or jsonb_typeof(p_payment -> 'option') is distinct from 'string' then
            raise exception 'Las condiciones de la compra no son válidas.' using errcode = '22023';
        end if;
        payment_option := p_payment ->> 'option';
        if payment_option not in ('efectivo', 'tarjeta', 'transferencia', 'credito') then
            raise exception 'La forma de pago no es válida.' using errcode = '22023';
        end if;
        if payment_option = 'efectivo' then
            if jsonb_typeof(p_payment -> 'cash_source') is distinct from 'string'
               or p_payment ->> 'cash_source' not in ('caja', 'cajero')
               or p_cash_source is distinct from p_payment ->> 'cash_source' then
                raise exception 'El origen del efectivo no es válido.' using errcode = '22023';
            end if;
        elsif jsonb_typeof(p_payment -> 'cash_source') is distinct from 'null'
              or p_cash_source is distinct from (case when payment_option = 'credito' then null else payment_option end) then
            raise exception 'Un pago no efectivo no puede afectar el cajón.' using errcode = '22023';
        end if;
        if payment_option = 'credito' then
            if p_provider_id is null or jsonb_typeof(p_payment -> 'credit_days') is distinct from 'number' then
                raise exception 'El crédito requiere proveedor y días de crédito.' using errcode = '22023';
            end if;
            if (p_payment ->> 'credit_days')::numeric < 0
               or (p_payment ->> 'credit_days')::numeric > 2147483647
               or (p_payment ->> 'credit_days')::numeric <> trunc((p_payment ->> 'credit_days')::numeric) then
                raise exception 'Los días de crédito no son válidos.' using errcode = '22023';
            end if;
            payment_days := (p_payment ->> 'credit_days')::integer;
        elsif jsonb_typeof(p_payment -> 'credit_days') is distinct from 'null' then
            raise exception 'El contado no admite días de crédito.' using errcode = '22023';
        end if;
    end if;
    select membership.username into uploader from public.business_memberships membership
    where membership.user_id = actor and membership.billar_id = p_billar_id
      and membership.role = 'manager' and membership.is_active
      and not membership.must_change_password
      and membership.username is not null and btrim(membership.username) <> ''
      and 'purchases' = any(membership.allowed_modules)
    for share;
    if not found then
        raise exception 'No tienes permiso para registrar compras.' using errcode = '42501';
    end if;
    payload := jsonb_build_object(
        'provider_id', p_provider_id, 'reference', p_reference,
        'cash_source', p_cash_source, 'items', p_items
    );
    if p_payment is not null then
        payload := payload || jsonb_build_object('payment', p_payment);
    end if;
    insert into public.staff_purchase_requests(request_id, billar_id, actor_id, request_payload)
    values (p_request_id, p_billar_id, actor, payload) on conflict (request_id) do nothing;
    select * into strict request_row from public.staff_purchase_requests
    where request_id = p_request_id for update;
    if request_row.billar_id <> p_billar_id or request_row.actor_id <> actor
       or request_row.request_payload <> payload then
        raise exception 'El identificador de compra ya fue utilizado.' using errcode = '23505';
    end if;
    if request_row.result is not null then return request_row.result; end if;
    if p_provider_id is not null then
        perform 1 from public.providers
        where id = p_provider_id and billar_id = p_billar_id and is_active for share;
        if not found then
            raise exception 'El proveedor no está activo en este billar.' using errcode = '42501';
        end if;
    end if;

    for item in select value from jsonb_array_elements(p_items) loop
        if jsonb_typeof(item) is distinct from 'object' then
            raise exception 'El detalle de compra no es válido.' using errcode = '22023';
        end if;
        if (select count(*) from jsonb_object_keys(item)) <> 5
           or jsonb_typeof(item -> 'product_id') is distinct from 'number'
           or jsonb_typeof(item -> 'quantity') is distinct from 'number'
           or jsonb_typeof(item -> 'cost_per_unit') is distinct from 'number'
           or jsonb_typeof(item -> 'pieces_per_unit') is distinct from 'number'
           or jsonb_typeof(item -> 'parent_id') is null
           or jsonb_typeof(item -> 'parent_id') not in ('null', 'number') then
            raise exception 'El detalle de compra no es válido.' using errcode = '22023';
        end if;
        if (item ->> 'product_id')::numeric <> trunc((item ->> 'product_id')::numeric)
           or (item ->> 'pieces_per_unit')::numeric <> trunc((item ->> 'pieces_per_unit')::numeric)
           or (item ->> 'parent_id')::numeric <> trunc((item ->> 'parent_id')::numeric) then
            raise exception 'La presentación de compra no es válida.' using errcode = '22023';
        end if;
        product_id := (item ->> 'product_id')::bigint;
        parent := (item ->> 'parent_id')::bigint;
        pieces := (item ->> 'pieces_per_unit')::integer;
        quantity := (item ->> 'quantity')::numeric;
        unit_cost := (item ->> 'cost_per_unit')::numeric;
        if product_id <= 0 or pieces <= 0 or quantity <= 0 or unit_cost < 0
           or (parent is not null and (parent <= 0 or parent = product_id))
           or product_id = any(requested_ids) then
            raise exception 'La cantidad, el costo o el producto no son válidos.' using errcode = '22023';
        end if;
        requested_ids := array_append(requested_ids, product_id);
        target_ids := array_append(target_ids, coalesce(parent, product_id));
        total := total + quantity * unit_cost;
    end loop;

    select array_agg(locked.id) into locked_ids from (
        select product.id from public.products product
        where product.billar_id = p_billar_id and (
            product.id = any(requested_ids) or product.id = any(target_ids)
            or product.parent_id = any(target_ids)
        )
        order by product.id for update
    ) locked;
    if exists (
        select 1 from public.products product where product.id = any(locked_ids)
          and (
              (product.stock > '-Infinity'::double precision and product.stock < 'Infinity'::double precision) is not true
              or product.stock_revision is null or product.stock_revision < 0
              or (product.cost is not null and
                  (product.cost > '-Infinity'::double precision and product.cost < 'Infinity'::double precision) is not true)
          )
    ) then
        raise exception 'Las existencias registradas no son válidas.' using errcode = '22023';
    end if;
    select jsonb_agg(jsonb_build_object(
        'product_id', product.id, 'stock', product.stock, 'cost', product.cost,
        'stock_revision', product.stock_revision
    ) order by product.id) into original_stock
    from public.products product where product.id = any(locked_ids);

    purchase_date := to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
    if payment_option = 'credito' then
        maturity := (purchase_date::timestamptz at time zone 'UTC')::date + payment_days;
        if maturity > date '9999-12-31' then
            raise exception 'El vencimiento excede el rango de fechas admitido.' using errcode = '22023';
        end if;
    end if;
    insert into public.purchases (
        billar_id, provider_id, total, date, reference, created_by, cash_source, cancelled,
        payment_condition, payment_method, credit_days, due_date, paid_amount, balance_due
    ) values (
        p_billar_id, p_provider_id, total::double precision, purchase_date,
        p_reference, uploader, p_cash_source, false,
        case when p_payment is null then null when payment_option = 'credito' then 'credito' else 'contado' end,
        case when payment_option = 'credito' then null else payment_option end,
        payment_days, maturity,
        case when p_payment is null then null when payment_option = 'credito' then 0 else total::double precision end,
        case when p_payment is null then null when payment_option = 'credito' then total::double precision else 0 end
    ) returning id into purchase_id;
    for item in select value from jsonb_array_elements(p_items) loop
        product_id := (item ->> 'product_id')::bigint;
        parent := (item ->> 'parent_id')::bigint;
        pieces := (item ->> 'pieces_per_unit')::integer;
        quantity := (item ->> 'quantity')::numeric;
        unit_cost := (item ->> 'cost_per_unit')::numeric;
        select * into product_row from public.products product
        where product.id = product_id and product.billar_id = p_billar_id
          and product.id = any(locked_ids) and product.is_active and product.is_promo = 0;
        if not found or btrim(product_row.name) = '' then
            raise exception 'El producto no está activo o no admite compras en este billar.'
                using errcode = '42501';
        end if;
        if product_row.parent_id is distinct from parent or product_row.pieces_per_unit is distinct from pieces then
            raise exception 'La presentación cambió; actualiza los productos.' using errcode = '40001';
        end if;
        select * into base from public.products product
        where product.id = coalesce(parent, product_id) and product.billar_id = p_billar_id
          and product.id = any(locked_ids) and product.parent_id is null
          and product.is_promo = 0 and product.is_active;
        if not found then
            raise exception 'El producto base no está activo en este billar.' using errcode = '42501';
        end if;
        if (base.price >= 0 and base.price < 'Infinity'::double precision) is not true
           or exists (
               select 1 from public.products child
               where child.billar_id = p_billar_id and child.parent_id = base.id
                 and child.id = any(locked_ids)
                 and (child.is_promo is distinct from 0 or child.pieces_per_unit is null or child.pieces_per_unit <= 0)
           ) then
            raise exception 'La información del producto base no es válida.' using errcode = '22023';
        end if;
        stock_quantity := (quantity * case when parent is null then 1 else pieces end)::double precision;
        cost_per_piece := (unit_cost / case when parent is null then 1 else pieces end)::double precision;
        if (stock_quantity > 0 and stock_quantity < 'Infinity'::double precision) is not true
           or base.stock + stock_quantity = base.stock
           or (cost_per_piece >= 0 and cost_per_piece < 'Infinity'::double precision) is not true then
            raise exception 'La cantidad o el costo convertido no son válidos.' using errcode = '22023';
        end if;
        update public.products set stock = stock + stock_quantity, cost = cost_per_piece,
            stock_revision = stock_revision + 1
        where id = base.id and billar_id = p_billar_id;
        update public.products child set cost = cost_per_piece * child.pieces_per_unit,
            stock_revision = child.stock_revision + 1
        where child.billar_id = p_billar_id and child.parent_id = base.id and child.id = any(locked_ids);
        insert into public.purchase_details (
            purchase_id, product_id, quantity, cost_per_unit, created_by, cancelled
        ) values (purchase_id, product_id, quantity::double precision, unit_cost::double precision, uploader, false);
        insert into public.inventory_movements (
            billar_id, product_id, movement_type, quantity, unit_cost,
            unit_price, reference_id, reference_type, notes
        ) values (
            p_billar_id, base.id, 'purchase', stock_quantity, cost_per_piece,
            base.price, purchase_id, 'purchases', 'Compra de personal'
        );
        details := details || jsonb_build_array(item || jsonb_build_object(
            'product_name', product_row.name, 'stock_product_id', base.id,
            'stock_quantity', stock_quantity, 'cost_per_piece', cost_per_piece
        ));
    end loop;
    select jsonb_build_object(
        'request_id', p_request_id, 'billar_id', p_billar_id, 'actor_id', actor,
        'purchase', to_jsonb(purchase), 'items', details, 'stock_before', original_stock,
        'stock_after', (select jsonb_agg(jsonb_build_object(
            'product_id', product.id, 'stock', product.stock, 'cost', product.cost,
            'stock_revision', product.stock_revision
        ) order by product.id) from public.products product where product.id = any(locked_ids))
    ) into receipt from public.purchases purchase where purchase.id = purchase_id;
    insert into public.staff_purchase_audit(request_id, billar_id, actor_id, purchase_id, receipt)
    values (p_request_id, p_billar_id, actor, purchase_id, receipt);
    update public.staff_purchase_requests set result = receipt where request_id = p_request_id;
    return receipt;
end;
$$;
revoke all on function public.record_staff_purchase(uuid, text, bigint, text, text, jsonb, jsonb)
from public, anon, authenticated;

-- Keep the original argument list and payload for already-persisted requests.
create or replace function public.record_staff_purchase(
    p_request_id uuid, p_billar_id text, p_provider_id bigint,
    p_reference text, p_cash_source text, p_items jsonb
)
returns jsonb
language sql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
    select public.record_staff_purchase(
        p_request_id, p_billar_id, p_provider_id, p_reference, p_cash_source, p_items, null::jsonb
    );
$$;
revoke all on function public.record_staff_purchase(uuid, text, bigint, text, text, jsonb)
from public, anon, authenticated;

-- SOURCE: staff_purchase_resolution_partial.sql
-- Preparation only. Requires staff_purchase_recording_partial.sql and
-- staff_provider_operations_partial.sql. Execution remains revoked.
-- Serializes with the original operation through its request row, never
-- interprets a missing row as proof that a delayed request cannot arrive.

set local lock_timeout = '3s';
set local statement_timeout = '30s';

create or replace function public.resolve_staff_purchase_request(
    p_request_id uuid,
    p_billar_id text,
    p_kind text,
    p_request_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
set lock_timeout = '3s'
as $$
declare
    actor uuid := auth.uid();
    metadata jsonb := auth.jwt() -> 'app_metadata';
    request_row record;
    receipt jsonb;
begin
    if actor is null or metadata ->> 'account_type' is distinct from 'staff'
       or metadata ->> 'billar_id' is distinct from p_billar_id then
        raise exception 'Se requiere una cuenta de personal de este billar.' using errcode = '42501';
    end if;
    if p_request_id is null or p_billar_id is null or btrim(p_billar_id) = ''
       or p_kind is null or p_kind not in ('purchase', 'provider')
       or jsonb_typeof(p_request_payload) is distinct from 'object' then
        raise exception 'La solicitud de resolución no es válida.' using errcode = '22023';
    end if;
    if p_kind = 'purchase' then
        if not (p_request_payload ?& array['provider_id', 'reference', 'cash_source', 'items'])
           or (select count(*) from jsonb_object_keys(p_request_payload))
              <> (case when p_request_payload ? 'payment' then 5 else 4 end) then
            raise exception 'El contenido de la compra no es válido.' using errcode = '22023';
        end if;
    else
        if not (p_request_payload ?& array['provider_id', 'operation', 'provider', 'product_ids'])
           or (select count(*) from jsonb_object_keys(p_request_payload)) <> 4 then
            raise exception 'El contenido del proveedor no es válido.' using errcode = '22023';
        end if;
    end if;
    perform 1 from public.business_memberships membership
    where membership.user_id = actor and membership.billar_id = p_billar_id
      and membership.role = 'manager' and membership.is_active
      and not membership.must_change_password
      and membership.username is not null and btrim(membership.username) <> ''
      and 'purchases' = any(membership.allowed_modules)
    for share;
    if not found then
        raise exception 'No tienes permiso para resolver compras y proveedores.' using errcode = '42501';
    end if;

    if p_kind = 'purchase' then
        insert into public.staff_purchase_requests(request_id, billar_id, actor_id, request_payload)
        values (p_request_id, p_billar_id, actor, p_request_payload)
        on conflict (request_id) do nothing;
        select * into strict request_row from public.staff_purchase_requests
        where request_id = p_request_id for update;
    else
        insert into public.staff_provider_requests(request_id, billar_id, actor_id, request_payload)
        values (p_request_id, p_billar_id, actor, p_request_payload)
        on conflict (request_id) do nothing;
        select * into strict request_row from public.staff_provider_requests
        where request_id = p_request_id for update;
    end if;
    if request_row.billar_id <> p_billar_id or request_row.actor_id <> actor
       or request_row.request_payload <> p_request_payload then
        raise exception 'El identificador de solicitud ya fue utilizado.' using errcode = '23505';
    end if;
    if request_row.result is not null then return request_row.result; end if;

    receipt := jsonb_build_object(
        'status', 'rejected', 'reason_code', 'not_applied_closed',
        'kind', p_kind, 'request_id', p_request_id,
        'billar_id', p_billar_id, 'actor_id', actor,
        'request_payload', p_request_payload
    );
    if p_kind = 'purchase' then
        update public.staff_purchase_requests set result = receipt
        where request_id = p_request_id;
    else
        update public.staff_provider_requests set result = receipt
        where request_id = p_request_id;
    end if;
    return receipt;
end;
$$;
revoke all on function public.resolve_staff_purchase_request(uuid, text, text, jsonb)
from public, anon, authenticated;

-- SOURCE: staff_business_profile.sql
-- Lectura limitada de identidad para el inicio de personal.
-- No concede SELECT ni escritura sobre billar_settings.

set local lock_timeout = '3s';
set local statement_timeout = '30s';

create or replace function public.staff_business_profile(requested_billar_id text)
returns table (billar_id text, business_name text, logo_url text, primary_color integer)
language plpgsql
stable
security definer
set search_path = pg_catalog, public, pg_temp
as $$
begin
    if not exists (
        select 1 from public.business_memberships m
        where m.user_id = auth.uid()
          and m.billar_id = requested_billar_id
          and m.role = 'manager' and m.username is not null
          and m.is_active and not m.must_change_password
    ) then
        raise exception 'La cuenta de personal no tiene acceso activo a este billar.'
            using errcode = '42501';
    end if;
    return query
        select s.billar_id::text, s.business_name::text, s.logo_url::text, s.primary_color
        from public.billar_settings s
        where s.billar_id = requested_billar_id;
    if not found then
        raise exception 'No se encontró la identidad del negocio.'
            using errcode = '55000';
    end if;
end;
$$;

revoke all on function public.staff_business_profile(text) from public, anon, authenticated;
grant execute on function public.staff_business_profile(text) to authenticated;
notify pgrst, 'reload schema';


do $seal$
declare
    function_name text;
    endpoint record;
begin
    foreach function_name in array array[
        'staff_sale_products', 'record_staff_sale', 'get_staff_sale_reconciliation',
        'reserve_staff_account', 'find_staff_creation_auth_user', 'finalize_staff_account',
        'stop_staff_password_recovery', 'complete_staff_password_change',
        'list_staff_accounts', 'update_staff_account', 'apply_staff_provider_operation',
        'record_staff_purchase', 'resolve_staff_purchase_request', 'staff_business_profile'
    ] loop
        if not exists (select 1 from pg_proc
            where pronamespace = 'public'::regnamespace and proname = function_name) then
            raise exception 'No se instalo la funcion %. Se revierte el lote.', function_name;
        end if;
        for endpoint in select oid, proname, pg_get_function_identity_arguments(oid) as arguments
            from pg_proc where pronamespace = 'public'::regnamespace and proname = function_name loop
            execute format('revoke all on function public.%I(%s) from public, anon, authenticated',
                endpoint.proname, endpoint.arguments);
            if has_function_privilege('authenticated', endpoint.oid, 'EXECUTE')
               or has_function_privilege('anon', endpoint.oid, 'EXECUTE') then
                raise exception 'No se pudo cerrar el acceso a %. Se revierte el lote.', function_name;
            end if;
        end loop;
    end loop;
end;
$seal$;

notify pgrst, 'reload schema';
commit;

-- Read-only preflight. Returns metadata and aggregate counts, never account rows.
-- Run against the current project before applying any staff rollout script.
with required_columns(name) as (
    values ('username'), ('full_name'), ('job_title'), ('allowed_modules'),
           ('must_change_password'), ('staff_revision')
),
required_tables(name) as (
    values ('business_memberships'), ('staff_account_requests'),
           ('staff_account_audit'), ('staff_sale_requests'),
           ('staff_sale_stock_products'), ('staff_sale_audit'),
           ('staff_provider_requests'), ('staff_provider_audit'),
           ('staff_purchase_requests'), ('staff_purchase_audit')
),
required_payment_columns(table_name, name) as (
    values ('providers', 'credit_days'), ('providers', 'preferred_payment_method'),
           ('purchases', 'payment_condition'), ('purchases', 'payment_method'),
           ('purchases', 'credit_days'), ('purchases', 'due_date'),
           ('purchases', 'paid_amount'), ('purchases', 'balance_due')
),
payment_column_info as (
    select required.table_name, required.name, attribute.attnum is not null as installed,
           format_type(attribute.atttypid, attribute.atttypmod) as data_type
    from required_payment_columns required
    left join pg_attribute attribute
      on attribute.attrelid = to_regclass('public.' || required.table_name)
     and attribute.attname = required.name and attribute.attnum > 0
     and not attribute.attisdropped
),
required_functions(name) as (
    values ('has_staff_module_access'), ('has_staff_pos_module_access'),
           ('can_access_inventory'), ('staff_sale_products'),
           ('record_staff_sale'), ('get_staff_sale_reconciliation'),
           ('reserve_staff_account'), ('find_staff_creation_auth_user'),
           ('finalize_staff_account'), ('stop_staff_password_recovery'),
           ('complete_staff_password_change'), ('list_staff_accounts'),
           ('update_staff_account'), ('apply_staff_provider_operation'),
           ('record_staff_purchase'), ('resolve_staff_purchase_request'),
           ('staff_business_profile')
),
allowed_modules(id) as (
    values ('quick_sale'), ('billiard_tables'), ('dine_in'),
           ('personal_account'), ('inventory'), ('purchases'),
           ('reports'), ('players'), ('settings')
),
membership_rows as (
    select to_jsonb(membership) as data
    from public.business_memberships membership
),
staff_rows as (
    select data from membership_rows where data ->> 'username' is not null
),
column_info as (
    select required.name, attribute.attnum is not null as installed,
           format_type(attribute.atttypid, attribute.atttypmod) as data_type,
           attribute.attnotnull as not_null,
           pg_get_expr(defaults.adbin, defaults.adrelid) as default_expression
    from required_columns required
    left join pg_attribute attribute
      on attribute.attrelid = to_regclass('public.business_memberships')
     and attribute.attname = required.name and attribute.attnum > 0
     and not attribute.attisdropped
    left join pg_attrdef defaults
      on defaults.adrelid = attribute.attrelid
     and defaults.adnum = attribute.attnum
),
table_info as (
    select required.name, relation.oid is not null as installed,
           relation.relrowsecurity as rls_enabled,
           has_table_privilege('anon', relation.oid, 'SELECT') as anon_select,
           has_table_privilege('authenticated', relation.oid, 'SELECT') as authenticated_select
    from required_tables required
    left join pg_class relation
      on relation.oid = to_regclass('public.' || required.name)
),
function_info as (
    select required.name, procedure.oid is not null as installed,
           pg_get_function_identity_arguments(procedure.oid) as arguments,
           pg_get_function_result(procedure.oid) as result_type,
           procedure.prosecdef as security_definer,
           has_function_privilege('anon', procedure.oid, 'EXECUTE') as anon_execute,
           has_function_privilege('authenticated', procedure.oid, 'EXECUTE') as authenticated_execute,
           has_function_privilege('service_role', procedure.oid, 'EXECUTE') as service_role_execute
    from required_functions required
    left join pg_proc procedure
      on procedure.pronamespace = to_regnamespace('public')
     and procedure.proname = required.name
),
membership_checks as (
    select count(*) as staff_rows,
           count(*) filter (
               where data ->> 'username' !~ '^[a-z0-9][a-z0-9._-]{2,31}$'
           ) as invalid_usernames,
           count(*) filter (
               where data ->> 'role' is distinct from 'manager'
           ) as non_manager_staff,
           count(*) filter (
               where length(btrim(coalesce(data ->> 'full_name', ''))) not between 1 and 120
                  or length(btrim(coalesce(data ->> 'job_title', ''))) not between 1 and 80
           ) as invalid_names_or_jobs,
           count(*) filter (
               where case when jsonb_typeof(data -> 'allowed_modules') = 'array' then
                   jsonb_array_length(data -> 'allowed_modules') = 0
                   or exists (
                       select 1 from jsonb_array_elements(data -> 'allowed_modules') module
                       where jsonb_typeof(module) is distinct from 'string'
                          or module #>> '{}' not in (select id from allowed_modules)
                   )
                   or (select count(distinct module)
                       from jsonb_array_elements(data -> 'allowed_modules') module)
                      <> jsonb_array_length(data -> 'allowed_modules')
               else true end
           ) as invalid_modules
    from staff_rows
)
select jsonb_build_object(
    'purchase_payment_columns', (select jsonb_agg(to_jsonb(c) order by table_name, name) from payment_column_info c),
    'membership_columns', (select jsonb_agg(to_jsonb(c) order by name) from column_info c),
    'staff_tables', (select jsonb_agg(to_jsonb(t) order by name) from table_info t),
    'staff_functions', (select jsonb_agg(to_jsonb(f) order by name, arguments) from function_info f),
    'membership_checks', (
        select to_jsonb(checks) || jsonb_build_object(
            'normalized_username_duplicate_groups', (
                select count(*) from (
                    select lower(btrim(data ->> 'username'))
                    from staff_rows
                    group by lower(btrim(data ->> 'username'))
                    having count(*) > 1
                ) duplicates
            )
        ) from membership_checks checks
    ),
    'membership_constraints', coalesce((
        select jsonb_agg(jsonb_build_object(
            'name', conname, 'validated', convalidated,
            'definition', pg_get_constraintdef(oid)
        ) order by conname)
        from pg_constraint
        where conrelid = to_regclass('public.business_memberships')
          and conname in ('business_memberships_username_format',
                          'business_memberships_allowed_modules_valid')
    ), '[]'::jsonb),
    'username_indexes', coalesce((
        select jsonb_agg(jsonb_build_object('name', indexname, 'definition', indexdef) order by indexname)
        from pg_indexes
        where schemaname = 'public' and tablename = 'business_memberships'
          and indexname = 'business_memberships_username_unique'
    ), '[]'::jsonb),
    'membership_policies', coalesce((
        select jsonb_agg(jsonb_build_object(
            'name', policyname, 'permissive', permissive, 'roles', roles,
            'command', cmd, 'using', qual, 'check', with_check
        ) order by policyname)
        from pg_policies
        where schemaname = 'public' and tablename = 'business_memberships'
    ), '[]'::jsonb)
) as diagnostic;
